"use client";
import {useState} from "react";
import Link from "next/link";
import {PackageCheck,Truck,MapPin,ArrowUpRight} from "lucide-react";
import {orderBucket,orderDate,orderNextStep,orderStatusLabel,type OrderRow} from "@/lib/vendor/order-workspace";
import s from "@/components/vendor/business-workspace.module.css";
export default function ShippingWorkspace({rows,issues,productCount,addressReady}:{rows:OrderRow[];issues:{id:string;name:string;missing:string}[];productCount:number;addressReady:boolean}){
 const [view,setView]=useState("all"),[search,setSearch]=useState("");
 const attention=rows.filter(r=>orderBucket(r)==="action").length,pickup=rows.filter(r=>r.detail==="Warehouse pickup").length;
 const visible=rows.filter(r=>(view==="all"||view==="prepare"&&orderBucket(r)==="action"||view==="pickup"&&r.detail==="Warehouse pickup"||view==="delivery"&&r.detail==="LinkWe delivery")&&`${r.reference} ${r.customer} ${r.title}`.toLowerCase().includes(search.trim().toLowerCase()));
 return <div className={s.stack}>
  <div className={s.grid}>{[{label:"To prepare",count:attention,Icon:PackageCheck,view:"prepare",text:"Review the order and choose your handover."},{label:"Delivery in progress",count:rows.length-pickup,Icon:Truck,view:"delivery",text:"Track each parcel through LinkWe."},{label:"Customer pickup orders",count:pickup,Icon:MapPin,view:"pickup",text:"Follow preparation and collection status."}].map(card=><button key={card.view} onClick={()=>setView(card.view)} className={s.card} style={{textAlign:"left",cursor:"pointer"}}><div className={s.row}><span className={s.label}>{card.label}</span><card.Icon size={22} aria-hidden/></div><p className={s.metric} style={{margin:"12px 0"}}>{card.count}</p><p className={s.muted}>{card.text}</p></button>)}</div>
  <div className={s.two}><section className={s.card} data-tour="shipping-orders"><div className={s.row}><h2 className={s.heading}>Active parcels</h2><span className={s.badge}>{rows.length} open</span></div><div className={s.toolbar}><input className={s.input} aria-label="Search parcels" placeholder="Order, customer or product…" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Parcel view" className={s.select} value={view} onChange={e=>setView(e.target.value)}><option value="all">All parcels</option><option value="prepare">To prepare</option><option value="delivery">Delivery</option><option value="pickup">Customer pickup</option></select></div>{!visible.length?<div className={s.empty}><PackageCheck size={32} style={{margin:"0 auto 12px"}}/><h3 className={s.heading}>{rows.length?"No matching parcels":"All clear for now"}</h3><p>{rows.length?"Change your search or parcel view.":"Paid physical orders appear here until delivery or collection is complete."}</p></div>:visible.map(row=><article className={s.divider} key={row.id}><div className={s.row}><strong>{row.reference}</strong><span className={`${s.badge} ${orderBucket(row)==="action"?s.warning:""}`}>{orderStatusLabel(row.status)}</span></div><p style={{margin:"10px 0 4px",fontWeight:650,fontSize:14}}>{row.title}</p><p className={s.muted}>{row.customer} · {row.detail} · {orderDate(row.createdAt)}</p><div className={s.row} style={{marginTop:14}}><p className={s.muted}>{orderNextStep(row)}</p><Link className={s.secondary} href={row.href}>Open order <ArrowUpRight size={15} aria-hidden/></Link></div></article>)}</section>
  <aside className={s.stack}><section className={s.card} data-tour="shipping-readiness"><p className={s.eyebrow}>Before the next order</p><h2 className={s.heading}>Delivery readiness</h2><p className={s.muted}>{productCount-issues.length} of {productCount} published physical products have the basic details checked.</p>{!addressReady&&<div className={s.error} style={{marginTop:14}}>Add your store address and region. <Link className={s.link} href="/dashboard/vendor/store/edit">Update store</Link></div>}{issues.length?<div>{issues.map(p=><Link key={p.id} href={`/dashboard/vendor/products/${p.id}/edit`} className={s.divider} style={{display:"block"}}><strong style={{fontSize:14}}>{p.name} ↗</strong><p className={s.muted}>Add {p.missing}</p></Link>)}</div>:<p className={s.badge} style={{marginTop:16}}>{productCount?"Product details are ready":"Add a physical product to begin"}</p>}</section><section className={s.hero}><h2 className={s.heading}>Pack. Label. Hand over.</h2><p className={s.muted}>Use the order reference on your parcel. Open the order to choose an available handover option and follow its instructions.</p><p className={s.muted} style={{marginTop:12}}>Delivery charges are calculated at checkout. Digital orders stay in your Orders workspace.</p><Link className={s.secondary} style={{marginTop:18}} href="/shipping-info">Delivery guide ↗</Link></section></aside></div>
 </div>;
}
